// ✅ Processa TODOS os itens recebidos
return $input.all().map(item => {
  const execution = item.json;
  const rawRunData = execution.data.resultData.runData;
  const nodes = [];

  for (const nodeName in rawRunData) {
    const runs = rawRunData[nodeName];
    runs.forEach(run => {
      let nodeOutput = run.data?.main?.[0]?.[0]?.json || {};

      if (nodeName !== 'OBTEM CONVERSAS DO BD') {
        const { transcript, transcriptGemini, intendedGemini, ...rest } = nodeOutput;
        nodeOutput = rest;
      }

      nodes.push({
        name: nodeName,
        status: run.executionStatus,
        startTime: run.startTime,
        executionTime: run.executionTime,
        output: nodeOutput,
        error: run.error || null
      });
    });
  }

  nodes.sort((a, b) => a.startTime - b.startTime);

  const mainNodeData  = nodes.find(n => n.name === 'OBTEM CONVERSAS DO BD')?.output || {};
  const valNodeData = nodes.find(n => n.output?.pedidoConcluido !== undefined)?.output || {};
  const orderNodeData = nodes.find(n => n.name.includes('Order'))?.output || {};

  // ✅ Retorna { json: ... } para cada item
  return {
    json: {
      execution_id:        String(execution.id),
      workflow_id:         execution.workflowId,
      status:              execution.status,
      conversation_id:     mainNodeData.conversationId || "—",
      agent_id:            mainNodeData.agentId || "—",
      order_id:            orderNodeData.orderId || "—",
      pedido_concluido:    valNodeData.pedidoConcluido || "nao",
      produto:             mainNodeData.product || "—",
      call_duration_valid: String(mainNodeData.intendedGemini?.call_duration_valid || "false"),
      execution_data:      { nodes }
    }
  };
});

return items
  .map(item => {
    const exec = item.json;
    if (!exec.startedAt || !exec.stoppedAt) return null;
    const durationSec = (new Date(exec.stoppedAt) - new Date(exec.startedAt)) / 1000;
    return { json: { ...exec, durationSec } };
  })
  .filter(item => item && item.json.durationSec > 8);

// ================= CONFIGURAÇÃO =================
const CONFIG = {
  nodeName: 'N8N to Supabase',
  fields: {
    cpf: 'cpf',
    cnpj: 'cnpj',
    sku: 'sku',
    email: 'email',
    pedidoConcluido: 'pedidoconcluido'
  }
};

const VALORES_VAZIOS = ['0', 'não informado', 'nao informado', '', 'null', 'undefined'];

// ================= HELPERS =================
function normalizarTexto(texto) {
  if (texto === undefined || texto === null) return '';
  return String(texto)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

function preenchido(valor) {
  if (valor === undefined || valor === null) return false;
  return !VALORES_VAZIOS.includes(normalizarTexto(valor));
}

function getRunData(inputJson) {
  if (inputJson?.data?.resultData?.runData) return inputJson.data.resultData.runData;
  if (inputJson?.data?.data?.resultData?.runData) return inputJson.data.data.resultData.runData;
  return {};
}

function getNodeOutput(runData, nodeName) {
  const targetKey = Object.keys(runData).find(k => k.trim() === nodeName.trim());
  if (!targetKey) return null;
  return runData[targetKey]?.[0]?.data?.main?.[0]?.[0]?.json || null;
}

// ================= LEITURA DA EXECUÇÃO =================
const execution = $input.first().json;
const runData = getRunData(execution);
const nodeOutput = getNodeOutput(runData, CONFIG.nodeName);

if (!nodeOutput) {
  return [{
    json: {
      deveAlertar: false,
      erro: `Node "${CONFIG.nodeName}" não encontrado no runData desta execução.`
    }
  }];
}

const cpf = nodeOutput[CONFIG.fields.cpf];
const cnpj = nodeOutput[CONFIG.fields.cnpj];
const sku = nodeOutput[CONFIG.fields.sku];
const email = nodeOutput[CONFIG.fields.email];
const pedidoConcluido = nodeOutput[CONFIG.fields.pedidoConcluido];

// ================= REGRAS DE VALIDAÇÃO =================
const temCpfOuCnpj = preenchido(cpf) || preenchido(cnpj);
const temSku = preenchido(sku);
const temEmail = preenchido(email);
const pedidoStatus = normalizarTexto(pedidoConcluido);
const pedidoNaoConcluido = pedidoStatus === 'nao' || pedidoStatus === 'não';

const deveAlertar = temCpfOuCnpj && temSku && temEmail && pedidoNaoConcluido; //temCpfOuCnpj && temSku && temEmail && 

// ================= EXTRAÇÃO & FORMATAÇÃO DA MENSAGEM =================
const executionId = execution.id || 'N/A';
const conversationId = nodeOutput.conversationId || 'N/A';
const orderId = nodeOutput.orderId || 'N/A';
const product = nodeOutput.product || 'N/A';
const agentId = nodeOutput.agentId || 'N/A';
const documento = preenchido(cpf) ? cpf : cnpj;
const tipoDocumento = preenchido(cpf) ? 'CPF' : 'CNPJ';

// Monta a mensagem final formatada em HTML
const message = `⚠️ <b>Pedido não concluído com dados completos!</b>
🆔 <b>Execution ID:</b> <code>${executionId}</code>
💬 <b>Conversation ID:</b> <code>${conversationId}</code>
📦 <b>Product:</b> ${product}
🤖 <b>Agent ID:</b> <code>${agentId}</code>
🧾 <b>${tipoDocumento}:</b> <code>${documento}</code>
📦 <b>SKU:</b> <code>${sku}</code>
📧 <b>Email:</b> <code>${email}</code>
📋 <b>Pedido Concluído:</b> ${pedidoConcluido}`;

// Retorna tudo limpo e estruturado
return [{
  json: {
    deveAlertar,
    executionId,
    conversationId,
    orderId,
    product,
    agentId,
    documento,
    tipoDocumento,
    sku: sku ?? null,
    email: email ?? null,
    pedidoConcluido: pedidoConcluido ?? null,
    criterios: { temCpfOuCnpj, temSku, temEmail, pedidoNaoConcluido },
    message
  }
}];
